CREATE SEQUENCE tournament_id_seq;
CREATE TABLE notice (notice_num INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, notice_title VARCHAR(100) NOT NULL, notice_contents VARCHAR(500) NOT NULL, notice_writer VARCHAR(20) NOT NULL, noti_reg_date DATE DEFAULT CURRENT_DATE, hit_num INTEGER NOT NULL DEFAULT 0);
CREATE TABLE board (board_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, board_title VARCHAR(100) NOT NULL, board_content VARCHAR(500) NOT NULL, board_writer VARCHAR(20) NOT NULL, board_reg_date DATE DEFAULT CURRENT_DATE);
CREATE TABLE "user" (user_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_name VARCHAR(20), real_name VARCHAR(30), password VARCHAR(255), phone_number VARCHAR(20), email VARCHAR(30) UNIQUE, birth_date DATE, gender VARCHAR(1) CHECK (gender IN ('M','F')), open_ranking INTEGER, region_ranking INTEGER, club_name VARCHAR(50), user_type VARCHAR(20), profile_image TEXT, role VARCHAR(10) NOT NULL DEFAULT 'USER' CHECK (role IN ('USER','ADMIN')));
CREATE TABLE comment (comment_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, board_id INTEGER NOT NULL REFERENCES board ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES "user", comment_depth INTEGER DEFAULT 0 CHECK (comment_depth >= 0), comment_content VARCHAR(500) NOT NULL, comment_writer VARCHAR(20) NOT NULL, comment_reg_date DATE DEFAULT CURRENT_DATE);
CREATE TABLE tournament (tournament_year INTEGER NOT NULL, tournament_id INTEGER NOT NULL DEFAULT nextval('tournament_id_seq'), tournament_name VARCHAR(100) NOT NULL, location VARCHAR(100), organizer_id INTEGER REFERENCES "user", start_date DATE, end_date DATE, entry_fee NUMERIC CHECK (entry_fee >= 0), event_info VARCHAR(500), prize_info VARCHAR(500), notes VARCHAR(500), PRIMARY KEY (tournament_year,tournament_id), CHECK(end_date >= start_date));
CREATE TABLE tournament_participant (participant_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tournament_year INTEGER NOT NULL, tournament_id INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES "user", regi_date DATE, final_rank INTEGER CHECK(final_rank > 0), notes VARCHAR(500), up_date DATE, FOREIGN KEY(tournament_year,tournament_id) REFERENCES tournament ON DELETE CASCADE, UNIQUE(tournament_year,tournament_id,user_id));
CREATE TABLE competition (competition_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tournament_year INTEGER NOT NULL, tournament_id INTEGER NOT NULL, competition_name VARCHAR(50), competition_type VARCHAR(50) CHECK(competition_type IN ('ROUND_ROBIN','SINGLE_ELIMINATION','DOUBLE_ELIMINATION','GROUP_STAGE')), match_format VARCHAR(50) CHECK(match_format IN ('SINGLES','DOUBLES','TEAM')), competition_order INTEGER, has_groups VARCHAR(1) CHECK(has_groups IN ('Y','N')), players_per_group INTEGER CHECK(players_per_group > 0), description VARCHAR(200), status VARCHAR(20) CHECK(status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')), FOREIGN KEY(tournament_year,tournament_id) REFERENCES tournament ON DELETE CASCADE);
CREATE TABLE "group" (group_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, competition_id INTEGER NOT NULL REFERENCES competition ON DELETE CASCADE, group_name VARCHAR(50), creat_date DATE, up_date DATE, UNIQUE(competition_id,group_name));
CREATE TABLE group_participant (group_id INTEGER NOT NULL REFERENCES "group" ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES "user", group_rank INTEGER CHECK(group_rank > 0), creat_date DATE, up_date DATE, PRIMARY KEY(group_id,user_id));
CREATE TABLE "match" (match_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, competition_id INTEGER NOT NULL REFERENCES competition ON DELETE CASCADE, group_id INTEGER REFERENCES "group", match_round INTEGER CHECK(match_round >= 0), match_number INTEGER, court_number INTEGER, status VARCHAR(20) CHECK(status IN ('SCHEDULED','IN_PROGRESS','COMPLETED','CANCELLED')), winner_side VARCHAR(10) CHECK(winner_side IN ('SIDE_A','SIDE_B','DRAW')), side_a_sets INTEGER DEFAULT 0, side_b_sets INTEGER DEFAULT 0, total_sets INTEGER DEFAULT 0, next_match_id INTEGER REFERENCES "match" ON DELETE SET NULL, notes VARCHAR(500), scheduled_at TIMESTAMPTZ, location VARCHAR(100), completed_at TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, CHECK(next_match_id <> match_id));
CREATE TABLE match_participant (match_participant_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, match_id INTEGER NOT NULL REFERENCES "match" ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES "user", side VARCHAR(10) NOT NULL CHECK(side IN ('SIDE_A','SIDE_B')), participant_order INTEGER CHECK(participant_order > 0), creat_date DATE, up_date DATE, UNIQUE(match_id,user_id), UNIQUE(match_id,side,participant_order));
CREATE TABLE set_score (set_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, match_id INTEGER NOT NULL REFERENCES "match" ON DELETE CASCADE, set_number INTEGER NOT NULL CHECK(set_number BETWEEN 1 AND 5), side_a_point INTEGER NOT NULL CHECK(side_a_point >= 0), side_b_point INTEGER NOT NULL CHECK(side_b_point >= 0), UNIQUE(match_id,set_number));
CREATE TABLE match_stats (match_id INTEGER NOT NULL REFERENCES "match" ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES "user", aces INTEGER, faults INTEGER, rallies INTEGER, win_rate DOUBLE PRECISION, PRIMARY KEY(match_id,user_id));
CREATE INDEX idx_comment_board ON comment(board_id);
CREATE INDEX idx_user_name ON "user"(real_name);
CREATE INDEX idx_user_club_gender ON "user"(club_name,gender);
CREATE INDEX idx_participant_user ON tournament_participant(user_id);
CREATE INDEX idx_competition_tournament ON competition(tournament_year,tournament_id);
CREATE INDEX idx_group_competition ON "group"(competition_id);
CREATE INDEX idx_group_participant_user ON group_participant(user_id);
CREATE INDEX idx_match_competition ON "match"(competition_id);
CREATE INDEX idx_match_scheduled ON "match"(scheduled_at);
CREATE INDEX idx_match_completed ON "match"(completed_at);
CREATE INDEX idx_match_participant_user ON match_participant(user_id);
CREATE INDEX idx_match_stats_user ON match_stats(user_id);
